// SPDX-License-Identifier: GPL-3.0
pragma solidity =0.6.12;

import "./interfaces/ICASwapFactory.sol";
import "./libraries/TransferHelper.sol";
import "./libraries/SwapLibrary.sol";
import "./interfaces/ICASwapRouter.sol";
import "./interfaces/IERC20.sol";
import "./interfaces/IWBOT.sol";

contract CASwapRouter is ICASwapRouter {
    address public immutable override factory;
    address public immutable override WBOT;

    modifier ensure(uint256 deadline) {
        require(deadline >= block.timestamp, "CASwapRouter: EXPIRED");
        _;
    }

    constructor(address _factory, address _wbot) public {
        require(_factory != address(0), "CASwapRouter: ZERO_ADDRESS");
        require(_wbot != address(0), "CASwapRouter: ZERO_ADDRESS");

        factory = _factory;
        WBOT = _wbot;
    }

    receive() external payable {
        require(msg.sender == WBOT, "CASwapRouter: ONLY_WBOT");  // only accept BOT via fallback from the WBOT contract
    }

    /**
     * @dev Gate liquidity entry through the Factory LP allowlist.
     */
    modifier onlyLpAllowed() {
        require(isLpAllowed(msg.sender), "CASwapRouter: LP_NOT_ALLOWED");
        _;
    }

    // **** ADD LIQUIDITY ****
    function _addLiquidity(
        address tokenA,
        address tokenB,
        uint256 amountADesired,
        uint256 amountBDesired,
        uint256 amountAMin,
        uint256 amountBMin
    ) private returns (uint256 amountA, uint256 amountB) {
        if (ICASwapFactory(factory).getPair(tokenA, tokenB) == address(0)) {
            ICASwapFactory(factory).createPair(tokenA, tokenB);
        }
        (uint256 reserveA, uint256 reserveB) = SwapLibrary.getReserves(factory, tokenA, tokenB);
        if (reserveA == 0 && reserveB == 0) {
            address pair = SwapLibrary.pairFor(factory, tokenA, tokenB);
            // Prevent pre-deposits from manipulating the initial liquidity ratio.
            require(IERC20(tokenA).balanceOf(pair) == 0 && IERC20(tokenB).balanceOf(pair) == 0, "CASwapRouter: PRE_DEPOSIT_DETECTED");

            (amountA, amountB) = (amountADesired, amountBDesired);
        } else {
            uint256 amountBOptimal = SwapLibrary.quote(amountADesired, reserveA, reserveB);
            if (amountBOptimal <= amountBDesired) {
                require(amountBOptimal >= amountBMin, "CASwapRouter: INSUFFICIENT_B_AMOUNT");
                (amountA, amountB) = (amountADesired, amountBOptimal);
            } else {
                uint256 amountAOptimal = SwapLibrary.quote(amountBDesired, reserveB, reserveA);
                require(amountAOptimal <= amountADesired, "CASwapRouter: EXCESSIVE_A_AMOUNT");
                require(amountAOptimal >= amountAMin, "CASwapRouter: INSUFFICIENT_A_AMOUNT");
                (amountA, amountB) = (amountAOptimal, amountBDesired);
            }
        }
    }

    function addLiquidity(
        address tokenA,
        address tokenB,
        uint256 amountADesired,
        uint256 amountBDesired,
        uint256 amountAMin,
        uint256 amountBMin,
        address to,
        uint256 deadline
    ) external override onlyLpAllowed ensure(deadline) returns (uint256 amountA, uint256 amountB, uint256 liquidity) {
        (amountA, amountB) = _addLiquidity(tokenA, tokenB, amountADesired, amountBDesired, amountAMin, amountBMin);
        address pair = SwapLibrary.pairFor(factory, tokenA, tokenB);
        TransferHelper.safeTransferFrom(tokenA, msg.sender, pair, amountA);
        TransferHelper.safeTransferFrom(tokenB, msg.sender, pair, amountB);
        liquidity = ICASwapPair(pair).mint(to);
    }

    function addLiquidityETH(
        address token,
        uint256 amountTokenDesired,
        uint256 amountTokenMin,
        uint256 amountETHMin,
        address to,
        uint256 deadline
    ) external override payable onlyLpAllowed ensure(deadline) returns (uint256 amountToken, uint256 amountETH, uint256 liquidity) {
        (amountToken, amountETH) = _addLiquidity(
            token,
            WBOT,
            amountTokenDesired,
            msg.value,
            amountTokenMin,
            amountETHMin
        );
        address pair = SwapLibrary.pairFor(factory, token, WBOT);
        TransferHelper.safeTransferFrom(token, msg.sender, pair, amountToken);
        IWBOT(WBOT).deposit{value: amountETH}();
        require(IWBOT(WBOT).transfer(pair, amountETH), "CASwapRouter: WBOT_TRANSFER_FAILED");
        liquidity = ICASwapPair(pair).mint(to);
        if (msg.value > amountETH) TransferHelper.safeTransferETH(msg.sender, msg.value - amountETH); // refund dust bot, if any
    }

    // **** REMOVE LIQUIDITY ****
    function removeLiquidity(
        address tokenA,
        address tokenB,
        uint256 liquidity,
        uint256 amountAMin,
        uint256 amountBMin,
        address to,
        uint256 deadline
    ) public override ensure(deadline) returns (uint256 amountA, uint256 amountB) {
        address pair = SwapLibrary.pairFor(factory, tokenA, tokenB);
        ICASwapPair(pair).transferFrom(msg.sender, pair, liquidity); // send LP shares to the pair
        (uint256 amount0, uint256 amount1) = ICASwapPair(pair).burn(to);
        (address token0, ) = SwapLibrary.sortTokens(tokenA, tokenB);
        (amountA, amountB) = tokenA == token0 ? (amount0, amount1) : (amount1, amount0);
        require(amountA >= amountAMin, "CASwapRouter: INSUFFICIENT_A_AMOUNT");
        require(amountB >= amountBMin, "CASwapRouter: INSUFFICIENT_B_AMOUNT");
    }

    function removeLiquidityETH(
        address token,
        uint256 liquidity,
        uint256 amountTokenMin,
        uint256 amountETHMin,
        address to,
        uint256 deadline
    ) public override ensure(deadline) returns (uint256 amountToken, uint256 amountETH) {
        (amountToken, amountETH) = removeLiquidity(
            token,
            WBOT,
            liquidity,
            amountTokenMin,
            amountETHMin,
            address(this),
            deadline
        );
        TransferHelper.safeTransfer(token, to, amountToken);
        IWBOT(WBOT).withdraw(amountETH);
        TransferHelper.safeTransferETH(to, amountETH);
    }

    function removeLiquidityWithPermit(
        address tokenA,
        address tokenB,
        uint256 liquidity,
        uint256 amountAMin,
        uint256 amountBMin,
        address to,
        uint256 deadline,
        bool approveMax,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external override returns (uint256 amountA, uint256 amountB) {
        address pair = SwapLibrary.pairFor(factory, tokenA, tokenB);
        uint256 value = approveMax ? uint256(-1) : liquidity;
        ICASwapPair(pair).permit(msg.sender, address(this), value, deadline, v, r, s);
        (amountA, amountB) = removeLiquidity(tokenA, tokenB, liquidity, amountAMin, amountBMin, to, deadline);
    }

    function removeLiquidityETHWithPermit(
        address token,
        uint256 liquidity,
        uint256 amountTokenMin,
        uint256 amountETHMin,
        address to,
        uint256 deadline,
        bool approveMax,
        uint8 v,
        bytes32 r,
        bytes32 s
    ) external override returns (uint256 amountToken, uint256 amountETH) {
        address pair = SwapLibrary.pairFor(factory, token, WBOT);
        uint256 value = approveMax ? uint256(-1) : liquidity;
        ICASwapPair(pair).permit(msg.sender, address(this), value, deadline, v, r, s);
        (amountToken, amountETH) = removeLiquidityETH(token, liquidity, amountTokenMin, amountETHMin, to, deadline);
    }

    // **** SWAP ****

    // Chain pair.swap along path. addresses[0] = next-hop recipient; addresses[1] = original
    // payer (msg.sender), used by each Pair for its fee-exempt lookup. The fixed-size array
    // keeps the call under the 0.6.x stack limit.
    function _swap(uint256[] memory amounts, address[] memory path, address _to) private {
        for (uint256 i; i < path.length - 1; i++) {
            (address input, address output) = (path[i], path[i + 1]);
            (address token0, ) = SwapLibrary.sortTokens(input, output);
            uint256 amountOut = amounts[i + 1];
            (uint256 amount0Out, uint256 amount1Out) = input == token0 ? (uint256(0), amountOut) : (amountOut, uint256(0));
            address to = i < path.length - 2 ? SwapLibrary.pairFor(factory, output, path[i + 2]) : _to;

            // addresses[1] preserves the original payer for Pair fee-exempt checks.
            address[2] memory addresses = [to, msg.sender];
            ICASwapPair(SwapLibrary.pairFor(factory, input, output)).swap(amount0Out, amount1Out, addresses, new bytes(0));
        }
    }

    /**
     * @dev Exact-input token swap. Fee-exempt callers quote the no-fee path.
     * @param path Ordered token path.
     */
    function swapExactTokensForTokens(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external override ensure(deadline) returns (uint256[] memory amounts) {
        // Fee-exempt callers quote the no-fee path; everyone else applies each pair's feeBps.
        amounts = isFeeExempt(msg.sender)
            ? SwapLibrary.getAmountsOutNoFee(factory, amountIn, path)
            : SwapLibrary.getAmountsOut(factory, amountIn, path);

        require(amounts[amounts.length - 1] >= amountOutMin, "CASwapRouter: INSUFFICIENT_OUTPUT_AMOUNT");
        TransferHelper.safeTransferFrom(path[0], msg.sender, SwapLibrary.pairFor(factory, path[0], path[1]), amounts[0]);
        _swap(amounts, path, to);
    }

    function swapExactETHForTokens(
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external payable override ensure(deadline) returns (uint256[] memory amounts) {
        require(path[0] == WBOT, "CASwapRouter: INVALID_PATH");
        amounts = isFeeExempt(msg.sender)
            ? SwapLibrary.getAmountsOutNoFee(factory, msg.value, path)
            : SwapLibrary.getAmountsOut(factory, msg.value, path);

        require(amounts[amounts.length - 1] >= amountOutMin, "CASwapRouter: INSUFFICIENT_OUTPUT_AMOUNT");
        IWBOT(WBOT).deposit{value: amounts[0]}();
        require(IWBOT(WBOT).transfer(SwapLibrary.pairFor(factory, path[0], path[1]), amounts[0]), "CASwapRouter: WBOT_TRANSFER_FAILED");
        _swap(amounts, path, to);
    }

    function swapExactTokensForETH(
        uint256 amountIn,
        uint256 amountOutMin,
        address[] calldata path,
        address to,
        uint256 deadline
    ) external override ensure(deadline) returns (uint256[] memory amounts) {
        require(path[path.length - 1] == WBOT, "CASwapRouter: INVALID_PATH");
        amounts = isFeeExempt(msg.sender)
            ? SwapLibrary.getAmountsOutNoFee(factory, amountIn, path)
            : SwapLibrary.getAmountsOut(factory, amountIn, path);

        require(amounts[amounts.length - 1] >= amountOutMin, "CASwapRouter: INSUFFICIENT_OUTPUT_AMOUNT");
        TransferHelper.safeTransferFrom(path[0], msg.sender, SwapLibrary.pairFor(factory, path[0], path[1]), amounts[0]);
        _swap(amounts, path, address(this));
        IWBOT(WBOT).withdraw(amounts[amounts.length - 1]);
        TransferHelper.safeTransferETH(to, amounts[amounts.length - 1]);
    }

    // **** VIEWS ****
    function quote(uint amountA, uint reserveA, uint reserveB) public pure override returns (uint amountB) {
        return SwapLibrary.quote(amountA, reserveA, reserveB);
    }

    function getAmountOut(uint amountIn, uint reserveIn, uint reserveOut, uint feeBps) public pure override returns (uint amountOut) {
        return SwapLibrary.getAmountOut(amountIn, reserveIn, reserveOut, feeBps);
    }

    function getAmountOutNoFee(uint amountIn, uint reserveIn, uint reserveOut) public pure override returns (uint amountOut) {
        return SwapLibrary.getAmountOutNoFee(amountIn, reserveIn, reserveOut);
    }

    function getAmountsOut(uint amountIn, address[] memory path) public view override returns (uint[] memory amounts) {
        return SwapLibrary.getAmountsOut(factory, amountIn, path);
    }

    function getAmountsOutNoFee(uint amountIn, address[] memory path) public view override returns (uint[] memory amounts) {
        return SwapLibrary.getAmountsOutNoFee(factory, amountIn, path);
    }

    /**
     * @dev Front-end helper that selects no-fee or normal quote by user status.
     * @param user Address whose fee-exempt status should be checked.
     */
    function getAmountsOutForUser(uint256 amountIn, address[] memory path, address user) public view override returns (uint256[] memory amounts) {
        amounts = isFeeExempt(user)
            ? SwapLibrary.getAmountsOutNoFee(factory, amountIn, path)
            : SwapLibrary.getAmountsOut(factory, amountIn, path);
    }

    /**
     * @dev Read effective fee-exempt status from the Factory.
     */
    function isFeeExempt(address user) public view returns (bool) {
        return ICASwapFactory(factory).isFeeExempt(user);
    }

    /**
     * @dev Read effective LP allowlist status from the Factory.
     */
    function isLpAllowed(address user) public view returns (bool) {
        return ICASwapFactory(factory).isLpAllowed(user);
    }
}

