// SPDX-License-Identifier: GPL-3.0
pragma solidity >=0.5.0;

interface ICASwapFactory {
  event PairCreated(address indexed token0, address indexed token1, address pair, uint256);
  event FeeToSetterTransferStarted(address indexed oldFeeToSetter, address indexed newFeeToSetter);
  event FeeToSetterTransferred(address indexed oldFeeToSetter, address indexed newFeeToSetter);
  event RouterSet(address indexed router);
  event PairFeeReceiverSet(address indexed tokenA, address indexed tokenB, address indexed receiver);
  event PairFeeBpsSet(address indexed tokenA, address indexed tokenB, uint256 feeBps);

  function getPair(address tokenA, address tokenB) external view returns (address pair);
  function allPairs(uint256) external view returns (address pair);
  function allPairsLength() external view returns (uint256);

  function createPair(address tokenA, address tokenB) external returns (address pair);

  function pairFeeReceivers(address tokenA, address tokenB) external view returns (address);
  function pairFeeBps(address tokenA, address tokenB) external view returns (uint256);

  function isFeeExempt(address user) external view returns (bool);
  function isLpAllowed(address user) external view returns (bool);
}

